  let opened=false,destroyed=false,busy=false,refreshing=false,pollTimer=null,view={section:'desk'},catalog={},snapshot=normalizeSnapshot(),users=[],invitations=[],activeDocument=null,activeRun=null,flash='',error='',inviteSecret=null,previousFocus=null,loadEpoch=0,sceneChangeEpoch=0,sceneChanging=false;
