  function heading(){if(view.mode==='edit-project')return ['维护项目','项目成员与负责人',''];if(view.mode==='task-reassign')return ['转派任务','工作交接',''];if(view.section==='detail')return[activeDocument?.title||'业务单','办理记录',`${workflowName(activeDocument?.type||activeDocument?.workflowId)} · ${statusLabel(activeDocument?.status)}`];if(['create','revise','edit-project'].includes(view.mode))return[view.type?workflowName(view.type):`新建${TERMS[view.kind]||''}`,'新建业务',''];if(view.mode==='password')return['修改密码','我的账号',''];if(view.mode==='reset-user')return['重设员工密码','账号管理',userName(view.id)];if(view.mode==='invite')return['邀请员工','员工入驻','由员工本人设置密码并进入办公室'];if(view.mode==='edit-user')return['员工权限','账号管理',userName(view.id)];if(view.mode==='action')return[ACTION_LABELS[view.operation]||'办理业务','人工确认',activeDocument?.title||''];return[{desk:'我的工作',flows:'发起业务',projects:'项目',products:'产品',inventory:'库存',people:'员工与权限',reports:'业务报表'}[view.section]||'业务工作台','疯狂办公室',actor().name?`${actor().name} · ${actor().department||'办公室'}`:''];}
