  function renderContent(){if(['create','revise','edit-project'].includes(view.mode))return view.type?renderDocumentForm(view.type):renderMasterForm(view.kind);if(view.mode==='password')return renderPassword();if(view.mode==='reset-user')return renderResetUser();if(view.mode==='invite')return renderInvite();if(view.mode==='edit-user')return renderUserForm();if(view.mode==='action')return renderActionForm();if(view.mode==='task-reassign')return renderTaskReassign();if(['task-complete','task-review'].includes(view.mode))return renderTaskComplete();if(view.section==='detail')return renderDetail();return {desk:renderDesk,flows:renderFlows,projects:renderProjects,products:renderProducts,inventory:renderInventory,people:renderPeople,reports:renderReports}[view.section]?.()||renderDesk();}
