  function renderUserForm(){const u=users.find(item=>item.id===view.id);if(!u)return renderEmpty('员工已变更，请刷新名册。');return `<form class="erp-form" data-erp-form="user" data-id="${e(u.id)}"><div class="erp-form-grid">${field('name','姓名',{required:true,value:u.name})}${field('department','部门',{value:u.department})}${field('title','岗位',{value:u.title})}${roleChecks(list(u.roles))}${u.status==='invited'?'<p class="erp-muted">员工尚未入驻，完成邀请后可登录。</p>':`<label class="erp-check-row erp-wide"><input type="checkbox" name="active" ${u.active!==false?'checked':''}>账号可以登录</label>`}</div><div class="erp-note">权限变更后，服务端按最新角色检查业务操作。请保留至少一名可用的系统管理员。</div>${formFooter('保存权限')}</form>`;}
  function renderAgentOutput(value){if(typeof value==='string')return `<p>${e(value)}</p>`;if(!value||typeof value!=='object')return '';return `${value.summary?`<p>${e(value.summary)}</p>`:''}${[['steps','办理步骤'],['checks','已核对'],['missing','待确认']].map(([key,label])=>list(value[key]).length?`<details ${key==='missing'?'open':''}><summary class="erp-muted">${label} · ${value[key].length} 项</summary><ul>${value[key].map(item=>`<li>${e(typeof item==='string'?item:textValue(item))}</li>`).join('')}</ul></details>`:'').join('')}`;}
  function renderDetail(){const d=activeDocument;if(!d)return renderEmpty('正在读取业务单…');const run=activeRun||d.run||d.agentRun,agentTasks=list(run?.tasks||d.agentTasks||d.agent?.tasks),events=list(run?.events||d.events||d.activity),approvals=list(d.approvals||d.approvalHistory),files=list(run?.artifacts||d.artifacts),input=d.input||{};if(safeFileUrl(d.reportUrl)&&!files.some(file=>file.url===d.reportUrl))files.unshift({name:'业务协作报告',url:d.reportUrl});return `<div class="erp-actions erp-detail-actions">${button('返回工作台','section','data-section="desk"')}${renderActions(d)}</div><dl class="erp-detail-summary">${[['业务编号',d.number||d.id],['当前状态',statusLabel(d.status)],['关联项目',project(d.projectId).name||'—'],['申请人',userName(d.requesterId||d.createdBy)],['创建时间',dateText(d.createdAt)],['更新时间',dateText(d.updatedAt)]].map(([label,value])=>`<div><dt>${e(label)}</dt><dd>${e(value)}</dd></div>`).join('')}</dl>${d.error||run?.error?`<div class="erp-form-errors">${e(d.error?.message||d.error||run?.error?.message||run?.error)}</div>`:''}${sectionHead('业务资料')}<dl class="erp-kv">${Object.entries(input).filter(([key])=>key!=='facts').map(([key,value])=>`<dt>${e(INPUT_LABELS[key]||key)}</dt><dd>${e(key==='employeeId'?userName(value):key==='operation'?OP_LABELS[value]||value:textValue(value))}</dd>`).join('')}</dl>${list(d.lines).length?`${sectionHead('产品明细')}${table(['产品','数量','单价','已办理'],d.lines.map(line=>[e(line.productName||line.name||product(line.productId).name||line.productId),e(d.type==='stocktake'?`实盘 ${line.countedQuantity??line.quantity} / 账面 ${line.systemQuantity??'—'}`:line.quantity),line.unitPriceCents!=null?money(line.unitPriceCents):'—',e(line.completedQuantity??line.receivedQuantity??line.shippedQuantity??line.postedQuantity??'—')]))}`:''}${list(run?.quoteEvidence?.quotes).length?`${sectionHead('真实报价来源','', '公开标价与配置、税费及服务条件分别核对')}${renderQuoteEvidence(run.quoteEvidence)}`:''}<div class="erp-detail-grid"><section>${sectionHead('虚拟员工协作',run?renderStatus(run.status):'')}${agentTasks.length?`<ol class="erp-timeline">${agentTasks.map(task=>`<li><span class="erp-person-mark" aria-hidden="true">V</span><div><strong>${e(task.name||task.agentName||task.employeeName||task.agent?.name||list(catalog.agents).find(agent=>agent.id===task.agentId)?.name||task.agentId||'虚拟员工')}<span class="erp-agent-identity">${e(statusLabel(task.status))}</span></strong><p>${e(task.title||task.goal||task.description||task.role||'')}</p>${task.result||task.output||task.error?`${renderAgentOutput(task.result||task.output||task.error)}`:''}</div></li>`).join('')}</ol>`:renderEmpty(d.status==='draft'?'业务单已保存，等待交给虚拟员工。':'暂无虚拟员工执行记录。')}${!agentTasks.length&&(d.proposal||d.agentReview||d.agentResult||run?.summary)?`<div class="erp-reading">${renderAgentOutput(d.proposal?.plan||d.agentReview||d.agentResult||run?.summary)}${d.proposal?.review?renderAgentOutput(d.proposal.review):''}</div>`:''}</section><section>${sectionHead('人工审批')}${approvals.length?`<ol class="erp-timeline">${approvals.map(item=>`<li><span class="erp-person-mark" data-kind="human" aria-hidden="true">H</span><div><strong>${e(item.actorName||item.name||userName(item.actorId||item.userId||item.approverId))}</strong><p>${e(item.note||item.comment||'')} ${e(statusLabel(item.status||item.decision||item.action))}</p><small>${e(dateText(item.createdAt||item.at||item.approvedAt))}</small></div></li>`).join('')}</ol>`:renderEmpty('尚未产生审批记录。')}${d.status==='awaiting_approval'&&d.approvalChain?.[d.approvalIndex]?`<div class="erp-note">等待${e(roleName(d.approvalChain[d.approvalIndex]))}审批 · 第 ${Number(d.approvalIndex)+1} / ${d.approvalChain.length} 级</div>`:''}${d.currentApproval||d.nextApproval?`<div class="erp-note">下一步：${e(textValue(d.currentApproval?.label||d.nextApproval?.label||d.currentApproval?.role||d.nextApproval?.role||'等待有权限的员工审批'))}</div>`:''}</section></div>${list(d.approvalHistory).length?`<details><summary class="erp-muted">历次审批记录</summary><ol class="erp-timeline">${d.approvalHistory.map(item=>`<li><div><strong>${e(item.actorName||userName(item.actorId))}</strong><p>${e(item.note||'')} · ${e(statusLabel(item.decision))}</p><small>${e(dateText(item.createdAt))}</small></div></li>`).join('')}</ol></details>`:''}${files.length?`${sectionHead('交付文件')}<ul class="erp-file-list">${renderFiles(files)}</ul>`:''}${events.length?`<details><summary class="erp-muted">查看执行记录（${events.length}）</summary><ol class="erp-timeline">${events.slice(-30).map(item=>`<li><div><strong>${e(item.agentName||item.actorName||item.type||'记录')}</strong><p>${e(item.message||item.text||item.summary||item.label||'')}</p><small>${e(dateText(item.createdAt||item.at||item.timestamp))}</small></div></li>`).join('')}</ol></details>`:''}`;}
  function renderActionForm(){const d=activeDocument,a=view.operation;if(!d)return renderEmpty('请重新打开业务单。');const fill=['receive','ship'].includes(a),returned=['return','reject'].includes(a),needsReference=['receive','ship','post','complete'].includes(a),lines=list(d.lines),key=a==='receive'?'receivedQuantity':'shippedQuantity';return `<form class="erp-form" data-erp-form="action" data-id="${e(d.id)}" data-operation="${e(a)}"><div class="erp-approval-box"><h2>${e(ACTION_LABELS[a]||'确认办理')}</h2><p>${e(d.title)} · ${e(workflowName(d.type))}</p>${needsReference?field('reference',a==='receive'?'收货凭证号':a==='ship'?'发货凭证号':'办理凭证号',{required:true,placeholder:'填写实际单号或可追溯凭证'}):''}${fill?`<div class="erp-line-list">${lines.map((line,index)=>{const remaining=Math.max(0,Number(line.quantity)-Number(line.completedQuantity??line[key]??0));return `<div data-erp-line="${index}">${field(`line_quantity_${index}`,`${line.productName||line.name||product(line.productId).name||line.productId} · 待${a==='receive'?'收':'发'} ${remaining}`,{type:'number',value:'',min:0,max:remaining,step:'1'}).replace('<input ','<input data-line-field="quantity" ')}<input type="hidden" data-line-field="lineId" value="${e(line.id||line.lineId)}"></div>`;}).join('')}</div>`:''}${field('note',returned?'退回原因':'办理意见',{type:'textarea',required:returned||d.type==='stocktake'&&['post','complete'].includes(a),placeholder:returned?'说明需要修改的内容':'填写实际核对情况'})}<div class="erp-actions">${button('返回业务单','open-document',`data-id="${e(d.id)}"`)}<button type="submit" class="erp-button ${returned?'erp-danger':'erp-primary'}">${e(ACTION_LABELS[a]||'确认')}</button></div></div></form>`;}
  function renderTaskReassign(){const task=snapshot.tasks.find(item=>item.id===view.id),p=project(task?.projectId),ids=new Set([...(p.members||[]),p.ownerId]);return `<form class="erp-form" data-erp-form="task-reassign" data-id="${e(view.id)}"><div class="erp-note">${e(task?.title||'任务')} · 当前负责人：${e(userName(task?.assigneeId))}</div>${field('assigneeId','接替员工',{required:true,options:options(users.filter(item=>item.active!==false&&ids.has(item.id)))})}${field('note','转派原因',{type:'textarea',required:true})}${formFooter('确认转派')}</form>`;}
  function renderTaskComplete(){const task=snapshot.tasks.find(item=>item.id===view.id),review=view.mode==='task-review',reject=['return','reject'].includes(view.operation);if(review)return `<form class="erp-form" data-erp-form="task-review" data-id="${e(view.id)}" data-operation="${e(view.operation)}"><div class="erp-approval-box"><h2>${e(task?.title||'工作任务')}</h2><div class="erp-reading">${e(task?.result||'暂无交付说明')}</div>${list(task?.evidence).map(item=>`<div class="erp-note"><strong>${e(item.name||'凭证')}</strong><br>${e(item.reference||textValue(item))}</div>`).join('')}${field('note',reject?'退回原因':'验收意见',{type:'textarea',required:reject})}${formFooter(reject?'退回补正':'确认验收')}</div></form>`;return `<form class="erp-form" data-erp-form="task-complete" data-id="${e(view.id)}">${field('result','交付说明',{type:'textarea',required:true,placeholder:task?.title||'填写实际完成的工作'})}${field('evidence','交付记录或凭证',{type:'textarea',required:true,placeholder:'每行填写一项文档地址、交付编号或可核对的记录'})}<div class="erp-note">提交后由项目负责人验收，通过后计入已完成工作记录。</div>${formFooter('提交交付')}</form>`;}
  async function openDocument(id){if(!opened)await open();navigate({section:'detail',id});activeDocument=snapshot.documents.find(item=>item.id===id)||null;activeRun=null;render();const epoch=loadEpoch;try{const data=await call('/api/erp/workitems/'+encodeURIComponent(id));if(!opened||view.section!=='detail'||view.id!==id||epoch!==loadEpoch)return;activeDocument={...documentFrom(data),...(data.reportUrl?{reportUrl:data.reportUrl}:{})};activeRun=data.run||activeDocument.run||activeDocument.agentRun||null;render();}catch(err){showError(err);}}
  function syncViewActions(){for(const control of root.querySelectorAll('[data-erp-action="view"]')){control.setAttribute('aria-pressed',String(scene?.mode===control.dataset.mode));control.setAttribute('aria-busy',String(sceneChanging));control.disabled=sceneChanging&&control.dataset.mode==='3d';}}
  async function switchView(mode){if(!scene||!['2d','3d'].includes(mode))return;const epoch=++sceneChangeEpoch;sceneChanging=true;syncViewActions();try{await scene.setMode(mode);}catch(err){showError(err);}finally{if(epoch===sceneChangeEpoch){sceneChanging=false;syncViewActions();}}}
  async function handleAction(event){const el=event.target.closest?.('[data-erp-action]');if(!el||!root.contains(el))return;const action=el.dataset.erpAction;if(action==='close'){close();return;}if(action==='view'){await switchView(el.dataset.mode);return;}if(busy)return;try{
    if(action==='section'){navigate({section:el.dataset.section});return;}
    if(action==='refresh'){await refresh();return;}
    if(action==='back'){back();return;}
    if(action==='all-documents'){navigate({section:'flows'});return;}
    if(action==='new-document'){navigate({section:'flows',mode:'create',type:el.dataset.type,projectId:el.dataset.projectId});return;}
    if(action==='new-master'){navigate({section:el.dataset.kind==='project'?'projects':'products',mode:'create',kind:el.dataset.kind});return;}
    if(action==='edit-project'){const record=project(el.dataset.id);navigate({section:'projects',mode:'edit-project',kind:'project',id:record.id});drafts.set(draftKey,{values:{name:record.name,customer:record.customer,ownerId:record.ownerId,members:record.members},rows:[]});render();return;}if(action==='task-reassign'){navigate({section:'projects',mode:'task-reassign',id:el.dataset.id});return;}if(action==='new-task'){navigate({section:'projects',mode:'create',kind:'task',projectId:el.dataset.id});return;}
    if(action==='password'){navigate({section:'people',mode:'password'});return;}if(action==='reset-user'){navigate({section:'people',mode:'reset-user',id:el.dataset.id,operation:el.dataset.operation==='reinvite'?'invite':el.dataset.operation||'reset'});return;}if(action==='invite'){navigate({section:'people',mode:'invite'});return;}
    if(action==='edit-user'){navigate({section:'people',mode:'edit-user',id:el.dataset.id});return;}
    if(action==='open-document'){await openDocument(el.dataset.id);return;}
    if(action==='document-action'){const id=assertAllowedAction(activeDocument,el.dataset.operation);if(id==='revise'){const d=activeDocument;view={section:'flows',mode:'revise',type:d.type,id:d.id,projectId:d.projectId};draftKey=keyFor(view);drafts.set(draftKey,{values:{title:d.title,projectId:d.projectId,...d.input},rows:list(d.lines).map(line=>({productId:line.productId,quantity:String(line.quantity),countedQuantity:String(line.countedQuantity??line.quantity),unitPrice:String((line.unitPriceCents||0)/100)}))});error='';render();return;}navigate({section:'detail',mode:'action',operation:id,id:activeDocument.id});return;}
    if(action==='task-review'){navigate({section:'projects',mode:'task-review',operation:el.dataset.operation,id:el.dataset.id});return;}if(action==='task-complete'){navigate({section:'projects',mode:'task-complete',id:el.dataset.id});return;}
    if(action==='add-line'||action==='remove-line'){capture();const saved=drafts.get(draftKey)||{values:{},rows:[]};if(action==='add-line')saved.rows.push({productId:'',quantity:'1',unitPrice:'',countedQuantity:'0'});else saved.rows.splice(Number(el.dataset.index),1);drafts.set(draftKey,saved);render();return;}
    if(action==='export'){downloadExport(el.dataset.kind);return;}if(action==='copy-invite'){if(!inviteSecret)return;try{await navigator.clipboard.writeText(inviteSecret.url);flash='邀请链接已复制。';render();}catch{showError(new Error('浏览器未允许复制，请选中链接手动复制。'));}return;}
    if(action==='dismiss-invite'){inviteSecret=null;render();return;}
  }catch(err){showError(err);}}
  function valuesFrom(form){const values={};for(const input of form.elements){if(!input.name||input.type==='button'||input.type==='submit')continue;if(['roles','members'].includes(input.name)){values[input.name]||=[];if(input.checked)values[input.name].push(input.value);}else values[input.name]=input.type==='checkbox'?input.checked:input.value.trim();}return values;}
  async function handleSubmit(event){const form=event.target.closest?.('[data-erp-form]');if(!form||!root.contains(form))return;event.preventDefault();if(busy)return;capture();if(!form.reportValidity())return;setBusy(true);showError('');try{const values=valuesFrom(form);let result;const kind=form.dataset.erpForm;
    if(kind==='password'){if(values.newPassword.length<12)throw new Error('新密码至少需要 12 个字符。');if(values.newPassword!==values.confirmPassword)throw new Error('两次新密码不一致。');await call('/api/erp/identity/password','POST',{currentPassword:values.currentPassword,newPassword:values.newPassword});form.reset();close();location.assign('/login');return;}if(kind==='reset-user'){result=await call('/api/erp/users/'+encodeURIComponent(form.dataset.id)+'/'+encodeURIComponent(form.dataset.operation||'reset'),'POST',{});const token=result.token||result.invitation?.token;if(!token)throw new Error('密码重设已提交，请核对服务返回的邀请记录。');inviteSecret={url:location.origin+'/join#token='+encodeURIComponent(token),expiresAt:result.expiresAt||result.invitation?.expiresAt};navigate({section:'people'});render();return;}if(kind==='document'){const payload=buildDocumentPayload(form.dataset.type,values,currentRows);if(view.mode==='revise'){delete payload.type;delete payload.projectId;payload.expectedVersion=activeDocument.version;result=await call('/api/erp/workitems/'+encodeURIComponent(form.dataset.id)+'/revise','POST',payload);}else result=await call('/api/erp/workitems','POST',payload);drafts.delete(draftKey);const d=documentFrom(result);await refresh({silent:true});await openDocument(d.id);return;}
    if(kind==='master'){const record=form.dataset.kind==='product'?{name:values.name,sku:values.sku,unit:values.unit,priceCents:parsePrice(values.price)}:{name:values.name,customer:values.customer,ownerId:values.ownerId,members:[...new Set([...(values.members||[]),values.ownerId])]};if(view.mode==='edit-project')result=await call('/api/erp/projects/'+encodeURIComponent(form.dataset.id),'PUT',record);else result=await call('/api/erp/masterdata','POST',{kind:form.dataset.kind==='product'?'products':'projects',record});drafts.delete(draftKey);await refresh({silent:true});navigate({section:form.dataset.kind==='product'?'products':'projects'});flash='已保存。';render();return;}
    if(kind==='invite'){result=await call('/api/erp/invitations','POST',{name:values.name,username:values.username,department:values.department,title:values.title,roles:values.roles||[]});const invitation=result.invitation||result,token=result.token||invitation.token;if(!token)throw new Error('邀请已创建，但服务未返回邀请链接。请在员工记录中核对。');inviteSecret={url:location.origin+'/join#token='+encodeURIComponent(token),expiresAt:invitation.expiresAt||result.expiresAt};drafts.delete(draftKey);await refresh({silent:true});navigate({section:'people'});render();return;}
    if(kind==='user'){await call('/api/erp/users/'+encodeURIComponent(form.dataset.id),'PUT',{name:values.name,department:values.department,title:values.title,roles:values.roles||[],active:values.active});drafts.delete(draftKey);await refresh({silent:true});navigate({section:'people'});flash='员工资料与权限已保存。';render();return;}
    if(kind==='task-reassign'){const task=snapshot.tasks.find(item=>item.id===form.dataset.id);if(!list(task?.allowedActions).includes('reassign'))throw new Error('当前任务不能转派，请刷新任务。');if(!values.note)throw new Error('请填写转派原因。');await call('/api/erp/tasks/'+encodeURIComponent(form.dataset.id)+'/reassign','POST',{assigneeId:values.assigneeId,note:values.note});drafts.delete(draftKey);await refresh({silent:true});navigate({section:'projects'});flash='任务已转派。';render();return;}if(kind==='task'){await call('/api/erp/tasks','POST',{projectId:values.projectId,title:values.title,assigneeId:values.assigneeId,dueDate:values.dueDate||undefined});drafts.delete(draftKey);await refresh({silent:true});navigate({section:'projects'});flash='任务已登记。';render();return;}
    if(kind==='task-review'){await call('/api/erp/tasks/'+encodeURIComponent(form.dataset.id)+'/'+encodeURIComponent(form.dataset.operation),'POST',{note:values.note});drafts.delete(draftKey);await refresh({silent:true});navigate({section:'projects'});flash=form.dataset.operation==='accept'?'交付已验收。':'任务已退回补正。';render();return;}if(kind==='task-complete'){await call('/api/erp/tasks/'+encodeURIComponent(form.dataset.id)+'/complete','POST',{result:values.result,evidence:values.evidence.split(/\n+/).map(item=>item.trim()).filter(Boolean).map(reference=>({name:'交付凭证',reference}))});drafts.delete(draftKey);await refresh({silent:true});navigate({section:'projects'});flash='交付已提交，等待负责人验收。';render();return;}
    if(kind==='action'){const action=assertAllowedAction(activeDocument,form.dataset.operation),payload={note:values.note||'',expectedVersion:activeDocument.version};if((['return','reject'].includes(action)||activeDocument.type==='stocktake'&&['post','complete'].includes(action))&&!payload.note)throw new Error(activeDocument.type==='stocktake'&&['post','complete'].includes(action)?'请填写盘点办理核对意见。':'请填写退回原因。');if(['receive','ship','post','complete'].includes(action)){if(!values.reference)throw new Error('请填写办理凭证号。');payload.reference=values.reference;if(['receive','ship'].includes(action))payload.lines=fulfillmentLines(activeDocument,currentRows,action);}await call('/api/erp/workitems/'+encodeURIComponent(form.dataset.id)+'/'+encodeURIComponent(action),'POST',payload);drafts.delete(draftKey);await refresh({silent:true});await openDocument(form.dataset.id);return;}
  }catch(err){showError(err);}finally{setBusy(false);}}
  function downloadExport(kind){let headers,rows,name;if(kind==='inventory'){headers=['产品编码','产品','单位','当前数量'];rows=snapshot.inventory.map(item=>[item.sku||product(item.productId).sku,item.name||product(item.productId).name,item.unit||product(item.productId).unit,item.quantity]);name='库存台账';}else{headers=['员工','项目','开始日期','结束日期','已验收任务数','期间提交','待验收','待办','逾期','交付验收','确认人','业务单号'];rows=snapshot.performance.flatMap(record=>list(record.facts?.employees).map(item=>[userName(item.employeeId),project(record.projectId).name,record.periodStart,record.periodEnd,item.completedTasks,item.submittedTasks??0,list(record.facts?.taskFacts).filter(task=>task.stateAtPeriodEnd==='submitted'&&task.assigneeIdAtPeriodEnd===item.employeeId).length,item.pendingTasks??0,item.overdueTasks??0,item.acceptedDeliveries??0,userName(record.confirmedBy),record.documentId]));name='员工工作记录';}if(!rows.length){showError(new Error('暂无可导出的已确认记录。'));return;}const url=URL.createObjectURL(new Blob([csvDocument(headers,rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'-'+new Date().toISOString().slice(0,10)+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function onKey(event){if(!opened)return;if(event.key==='Escape'&&!busy){event.preventDefault();close();return;}if(event.key==='Tab'){const focusable=[...root.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||!root.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}
  function handleChange(event){capture();if(event.target?.name==='employeeId'&&view.type==='resource')render();}function onVisibility(){if(opened&&document.visibilityState==='visible')void refresh({silent:true});}
  root.addEventListener('click',handleAction);root.addEventListener('submit',handleSubmit);root.addEventListener('input',capture);root.addEventListener('change',handleChange);document.addEventListener('keydown',onKey);document.addEventListener('visibilitychange',onVisibility);
  async function open(section='desk',context={}){if(destroyed)return;const wasOpen=opened;if(!wasOpen)previousFocus=document.activeElement;opened=true;root.hidden=false;loadEpoch++;draftKey='';view={section:SECTIONS.some(([id])=>id===section)?section:'desk',...context};draftKey=keyFor(view);error='';if(!wasOpen){inerted=[];for(const sibling of container.children){if(sibling!==root&&!sibling.inert){sibling.inert=true;inerted.push(sibling);}}}render();root.querySelector('[data-erp-action="close"]')?.focus();if(pollTimer)clearInterval(pollTimer);pollTimer=setInterval(()=>{if(opened&&!busy&&document.visibilityState!=='hidden')void refresh({silent:true});},5000);await refresh();}
  function close(){if(!opened)return;capture();opened=false;loadEpoch++;root.hidden=true;root.innerHTML='';inviteSecret=null;if(pollTimer)clearInterval(pollTimer);pollTimer=null;for(const sibling of inerted)sibling.inert=false;inerted=[];previousFocus?.focus?.();onClose();}
  function destroy(){close();destroyed=true;root.removeEventListener('click',handleAction);root.removeEventListener('submit',handleSubmit);root.removeEventListener('input',capture);root.removeEventListener('change',handleChange);document.removeEventListener('keydown',onKey);document.removeEventListener('visibilitychange',onVisibility);root.remove();drafts.clear();mutationKeys.clear();}
  return {open,close,destroy,refresh,openDocument,updateSession(value){session=value||{};if(opened)render();},get isOpen(){return opened;},get state(){return {section:view.section,mode:view.mode,snapshot,currentUser:actor(),busy};}};
